CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, user TEXT UNIQUE NOT NULL, name TEXT, level TEXT NOT NULL, pass TEXT NOT NULL, created_at TEXT, muted INTEGER DEFAULT 0, banned INTEGER DEFAULT 0, note TEXT, deleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, account_id TEXT NOT NULL, created_at TEXT, expires_at TEXT);
CREATE INDEX IF NOT EXISTS idx_sessions_acc ON sessions(account_id);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, name TEXT, role TEXT, owner TEXT, muted INTEGER DEFAULT 0, banned INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, from_id TEXT, from_name TEXT, from_level TEXT, target_type TEXT, target_id TEXT, target_name TEXT, reason TEXT NOT NULL, images TEXT, status TEXT NOT NULL, handler_id TEXT, handler_name TEXT, action TEXT, note TEXT, created_at TEXT, handled_at TEXT);
CREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status);
CREATE INDEX IF NOT EXISTS idx_reports_from ON reports(from_id);
CREATE TABLE IF NOT EXISTS logs (id TEXT PRIMARY KEY, at TEXT, actor TEXT, level TEXT, text TEXT);
CREATE INDEX IF NOT EXISTS idx_logs_at ON logs(at);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, who TEXT, who_id TEXT, type TEXT, text TEXT, images TEXT, date TEXT, at TEXT, pinned INTEGER DEFAULT 0, hidden INTEGER DEFAULT 0, created_at TEXT);
CREATE INDEX IF NOT EXISTS idx_posts_created ON posts(created_at);
CREATE TABLE IF NOT EXISTS notices (id TEXT PRIMARY KEY, text TEXT, author TEXT, author_id TEXT, urgent INTEGER DEFAULT 0, pinned INTEGER DEFAULT 0, images TEXT, at TEXT, created_at TEXT);
CREATE INDEX IF NOT EXISTS idx_notices_pin ON notices(pinned);
CREATE TABLE IF NOT EXISTS codes (code TEXT PRIMARY KEY, used INTEGER DEFAULT 0, used_by TEXT, used_at TEXT, created_at TEXT, note TEXT, batch TEXT);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT, updated_at TEXT);
